import json,os,re
base='/home/USER/runs/paper/glm-hpl-u1-turns/frozen/held-out-2/play/users/u060/system/state/workspace/programs'
pairs=json.load(open(base+'/task-e1153969.json'))
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
for i in (1,2,3):
    p={'input':G[f'Demo pair {i} input'],'output':G[f'Demo pair {i} output']}
    if p not in pairs: pairs.append(p)
json.dump(pairs,open(base+'/task-e1153969.json','w'))
ns={}; exec(open(base+'/task-e1153969.py').read(),ns)
print(len(pairs), all(ns['transform'](p['input'])==p['output'] for p in pairs))
